      SUBROUTINE DECMIS(NELMN)      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'KNAME.CIN'      INCLUDE 'LNAME.CIN'      INCLUDE 'PARDAT.CIN'      INCLUDE 'PARVAL.CIN'      EQUIVALENCE (FAKE,LAKE)C      CALL FNDLAB(KNAME,NELMN)      IF (NELMN .EQ. 0) THEN        CALL RDFAIL        WRITE (NOUT,920) KNAME(1:LNAME)      ENDIF      IPARM = 9      IPTYP(9) = 1      IPDAT(9) = 102      LAKE = NELMN      PDATA(9) = FAKE      CALL RDBACKC      RETURNC-----------------------------------------------------------------------  920 FORMAT (' *** ERROR *** UNKNOWN BEAM ELEMENT "',A,'"'/' ')C-----------------------------------------------------------------------      END